from pathlib import Path
import json,hashlib

def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def scalars(p):
 rows=[]
 for line in Path(p).read_text().splitlines():
  r=json.loads(line)
  if r['type'] in ('pair','failure'):
   c=r.get('comparison',{});rows.append([r['id'],r['type']]+[c.get(k) for k in ['passed','points','worst_error','worst_signal']])
 return rows
report={}
for stage,prefix in [('stage1','/tmp/neospice-joss-checkpoint29-'),('stage2','/tmp/neospice-joss-checkpoint29-stage2-')]:
 for version in ['42','47']:
  for population,total in [('comprehensive',34),('ths4131',5),('tlv3201',1)]:
   d=Path(prefix+population+version);m=json.loads((d/'manifest.json').read_text());s=json.loads((d/'summary.json').read_text())
   assert m['complete'] and m['evidence_valid'] and m['verify_only'] and m['inventory_before']==m['inventory_after']
   for r in m['artifacts'].values():assert sha(r['path'])==r['sha256'] and Path(r['path']).stat().st_size==r['bytes']
   assert len(s['cases'])==total
   accepted=sum(c['accepted'] for c in s['cases']);assert m['returncode']==(0 if accepted==total else 1)
   old=Path('/tmp/neospice-joss-checkpoint27-'+('tlv' if population=='tlv3201' else population)+version)
   pair_records=[json.loads(x) for x in (d/'pairs.jsonl').read_text().splitlines()]
   report[stage+'-'+population+version]=dict(total=total,accepted=accepted,failed=[c['id'] for c in s['cases'] if not c['accepted']],returncode=m['returncode'],scalars_equal_checkpoint27=scalars(d/'pairs.jsonl')==scalars(old/'pairs.jsonl'),manifest_sha256=sha(d/'manifest.json'))
   if population=='tlv3201':
    r=next(r for r in pair_records if r['type']=='pair');assert len(r['reference_edges'])==len(r['actual_edges'])==6
    report[stage+'-'+population+version]['informational_waveform_passed']=r['informational_waveform_comparison']['passed']
r=dict(results=report,scope='All twelve verification-only runs. Artifact hashes and within-run source/build inventories checked; historical build paths have subsequently been rebuilt, so no claim their current bytes equal stage1 inventories. No new performance timings.',script=Path(__file__).read_text())
p=Path('docs/evidence/joss/2026-09-11-checkpoint29-benchmark-audit.json');assert not p.exists();p.write_text(json.dumps(r,indent=2)+'\n');print(json.dumps(report,indent=2))
